import copy


class ParcelCrate:
    """An owner-labelled, mutation-isolated collection of parcel items."""

    def __init__(self, owner, items=()):
        if not isinstance(owner, str) or not owner:
            raise ValueError("owner must be a nonempty string")
        if isinstance(items, (str, bytes)):
            raise ValueError("items must be a non-string iterable")
        try:
            self._items = copy.deepcopy(list(items))
        except TypeError:
            raise ValueError("items must be iterable") from None
        self._owner = owner

    @property
    def owner(self):
        """Return the crate owner identifier."""
        return self._owner

    def add(self, item):
        """Append a mutation-isolated copy of item."""
        self._items.append(copy.deepcopy(item))

    def discard(self, item):
        """Remove and return a copy of the first item equal to item."""
        for index, stored in enumerate(self._items):
            if stored == item:
                return copy.deepcopy(self._items.pop(index))
        raise ValueError("item is not present")

    def contents(self):
        """Return an ordered deep copy of all stored items."""
        return list(self._items)

    def empty(self):
        """Return True exactly when the crate contains no items."""
        return not self._items

    def __len__(self):
        return len(self._items)

